function buildDoc(f){
  f=f||{};
  var kind=String(f.kind||'隐私政策').trim()||'隐私政策';
  var entity=String(f.entity||'示例公司').trim()||'示例公司';
  var region=String(f.region||'中国大陆').trim()||'中国大陆';
  var date=String(f.date||'2026-08-19').trim()||'2026-08-19';
  var lines=['# '+kind+'（模板）','','- 主体：'+entity, '- 适用地区：'+region, '- 生效日期：'+date, ''];
  if(kind.indexOf('隐私')>=0){
    lines.push('## 我们收集的信息','我们可能收集您在使用服务过程中主动提供或系统自动记录的信息，包括账户信息、使用日志与设备信息。');
    lines.push('## 信息的使用','用于提供与改进服务、保障安全及履行法定义务。');
    lines.push('## 您的权利','您有权查询、更正或删除您的个人信息，并可撤回已授予的授权。');
  } else if(kind.indexOf('条款')>=0 || kind.indexOf('服务')>=0){
    lines.push('## 服务说明','本条款约定您使用'+entity+'提供的服务时的权利与义务。');
    lines.push('## 账户责任','您须妥善保管账户凭证，因保管不善导致的损失由您自行承担。');
    lines.push('## 免责声明','在适用法律允许的最大范围内，'+entity+'不对间接损失承担责任。');
  } else {
    lines.push('## 适用范围','本准则适用于'+entity+'全体成员及相关合作方。');
    lines.push('## 基本准则','尊重、诚信、合规、协作。');
    lines.push('## 违规处理','违反准则将视情节给予提醒、警告或相应处理。');
  }
  return {kind:kind, entity:entity, markdown:lines.join('\n')};
}
var EXPORTS={buildDoc:buildDoc};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.TermsForgePure = EXPORTS; }
